import java.io.*;

public class Main {
    static byte[] buf;
    static int pos;

    static void skip() {
        while (pos < buf.length && buf[pos] <= ' ') pos++;
    }

    static String next() {
        skip();
        int s = pos;
        while (pos < buf.length && buf[pos] > ' ') pos++;
        return new String(buf, s, pos - s);
    }

    static long nextLong() {
        skip();
        boolean neg = buf[pos] == '-';
        if (neg) pos++;
        long r = 0;
        while (pos < buf.length && buf[pos] > ' ') r = r * 10 + (buf[pos++] - '0');
        return neg ? -r : r;
    }

    static int nextInt() {
        return (int) nextLong();
    }

    public static void main(String[] args) throws IOException {
        buf = System.in.readAllBytes();
        int rows = nextInt(), cols = nextInt();
        int N = rows * cols;
        boolean[] wall = new boolean[N];
        int[] tr = new int[N];
        int wc = nextInt();
        for (int i = 0; i < wc; i++) {
            int r = nextInt(), c = nextInt();
            wall[r * cols + c] = true;
        }
        int tc = nextInt();
        for (int i = 0; i < tc; i++) {
            int r = nextInt(), c = nextInt();
            tr[r * cols + c] = 1;
        }
        int s = nextInt() * cols;
        s += nextInt();
        int e = nextInt() * cols;
        e += nextInt();
        if (wall[s] || wall[e]) {
            System.out.println("-1 0");
            return;
        }
        // BFS by distance; best[] = max treasures over shortest paths, final when a cell is popped.
        int[] dist = new int[N], best = new int[N], q = new int[N];
        java.util.Arrays.fill(dist, -1);
        int head = 0, tail = 0;
        dist[s] = 0;
        best[s] = tr[s];
        q[tail++] = s;
        int[] dr = {1, -1, 0, 0}, dc = {0, 0, 1, -1};
        while (head < tail) {
            int u = q[head++], r = u / cols, c = u % cols;
            for (int d = 0; d < 4; d++) {
                int nr = r + dr[d], nc = c + dc[d];
                if (nr < 0 || nr >= rows || nc < 0 || nc >= cols) continue;
                int z = nr * cols + nc;
                if (wall[z]) continue;
                if (dist[z] < 0) {
                    dist[z] = dist[u] + 1;
                    best[z] = best[u] + tr[z];
                    q[tail++] = z;
                } else if (dist[z] == dist[u] + 1) {
                    best[z] = Math.max(best[z], best[u] + tr[z]);
                }
            }
        }
        System.out.println(dist[e] < 0 ? "-1 0" : dist[e] + " " + best[e]);
    }
}

