	s, e := sr*cols+sc, er*cols+ec
	if wall[s] || wall[e] {
		fmt.Println("-1 0")
		return
	}
	// BFS by distance; best[] = max treasures over shortest paths, final when a cell is popped.
	dist := make([]int, N)
	for i := range dist {
		dist[i] = -1
	}
